# owner: platform
"""Contact sheet for substitute teachers."""

from operator import attrgetter

from rosterkit.errors import ProjectError

def _cells(student):
    if not student.email:
        raise ProjectError(
            f"No email for {student.display_name}"
        )
    name = student.display_name
    return (name, student.section, student.email)

def _line(cells, widths):
    padded = zip(cells, widths)
    return "  ".join(
        text.ljust(wide) for text, wide in padded
    ).rstrip()

def _widths(rows):
    columns = zip(*rows)
    return [max(map(len, item)) for item in columns]

# ---
def contact_rows(students):
    if not students:
        raise ProjectError("No students to list")
    getter = attrgetter("display_name")
    ordered = sorted(students, key=getter)
    rows = [_cells(item) for item in ordered]
    widths = _widths(rows)
    return [_line(cells, widths) for cells in rows]

